// grupos) y "el viernes" como el día 15 (era el 13).
const textoParaDatos = String(datos.mensajeTexto || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const NUMEROS = { uno: 1, una: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5, seis: 6, siete: 7, ocho: 8, nueve: 9, diez: 10, once: 11, doce: 12, trece: 13, catorce: 14, quince: 15, dieciseis: 16, diecisiete: 17, dieciocho: 18, diecinueve: 19, veinte: 20, treinta: 30 };
const N_RE = '(\\d{1,3}|' + Object.keys(NUMEROS).join('|') + ')';
function personasDelTexto(t) {
  // "2 adultos y 2 niños": la suma la hace el modelo.
  if (/\b(?:ninos?|ninas?|nenes?|bebes?|crios|peques|menores)\b/.test(t)) return null;
  const valores = new Set();
  const aNum = s => (/^\d+$/.test(s) ? parseInt(s, 10) : NUMEROS[s]);
  // "para 8", "somos 8", "seremos ocho", "mesa para 8" (no "para 21 de diciembre", "para las 21")
