      p_fecha: nuevos.fecha, p_hora: nuevos.hora, p_personas: nuevos.personas, p_zona: nuevos.zona,
      p_duracion_minutos: duracionPara(nuevos.personas), p_aplicar: false
    });
  } catch (e) {
    return salida(`Perdona, no encuentro esa reserva: puede que ya esté anulada o que ya haya pasado. Si necesitas ayuda, ${contactoRestaurante}.`, { intencion: 'general' });
  }
  if (motivo) return salida(`${motivo} ¿Te viene bien otra hora u otro día?`, enCurso);
  return salida(`Te cambio la reserva:\n\n❌ Antes: ${textoReserva(reserva)}\n✅ Ahora: ${textoReserva(nuevos)}\n\n¿Confirmo el cambio? (responde *sí* o *no*)`,
    { datosReservaEnCurso: { gestion: { tipo: 'modificar', reserva, nuevos } }, estadoSesion: 'pendiente_modificacion' });
}

// 3) Grupos grandes: por WhatsApp solo hasta maxPersonas (por defecto, la
// mesa más grande); para más, se remite al restaurante.
if (parsed && parsed.accion !== 'cancelar' && maxPersonas && datosMergeados.personas > maxPersonas) {
  datosMergeados.personas = null;
  return [{ json: {
    ...datos,
    contexto: contextoSalida,
    intencion: 'reserva',
    accionReserva: 'continuar',
    datosReservaEnCurso: datosMergeados,
    mensajeRespuesta: mensajeGrupo()
  }}];
}

// Comprobación inmediata de fecha y hora: formato, que no hayan pasado y
// que el restaurante abra. Si algo falla se borra ese dato, se explica al
// cliente y no se avanza.
let correccionFechaHora = null;
if (parsed && parsed.accion !== 'cancelar') {
  const cambio = datosMergeados.fecha !== (datosAnteriores.fecha || null)
    || datosMergeados.hora !== (datosAnteriores.hora || null);
  if (cambio || parsed.accion === 'crear_reserva') {
    const limpiar = (...campos) => campos.forEach(c => { datosMergeados[c] = null; });
    if (datosMergeados.fecha && !esFechaValida(datosMergeados.fecha)) {
      correccionFechaHora = 'No he entendido bien la fecha. ¿Para qué día quieres la reserva?';
      limpiar('fecha');
    } else if (datosMergeados.hora && !esHoraValida(datosMergeados.hora)) {
      correccionFechaHora = 'No he entendido bien la hora. ¿A qué hora quieres la reserva?';
      limpiar('hora');
    } else {
      const pasado = reservaEnPasado(datosMergeados.fecha, datosMergeados.hora, ahoraMadrid());
      if (pasado) {
        correccionFechaHora = pasado.motivo;
        limpiar(...pasado.limpiar);
      } else if (datosMergeados.fecha && datosMergeados.hora) {
        // El horario está en la config del restaurante. Si no se puede
        // leer, se sigue: "Verificar disponibilidad" lo comprueba al final.
        try {
          const restData = await this.helpers.httpRequest({
            method: 'GET',
            url: `${$env.SUPABASE_URL}/rest/v1/restaurants?id=eq.${datos.restaurant_id}&select=config`,
            headers: { 'apikey': $env.SUPABASE_SERVICE_ROLE_KEY, 'Authorization': 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY },
            json: true,
          });
          const h = horarioReserva(restData?.[0]?.config || {}, datosMergeados.fecha, datosMergeados.hora);
          if (!h.disponible) {
            correccionFechaHora = h.motivo + (h.cerradoEseDia ? ' ¿Te viene bien otro día?' : ' ¿A qué hora te viene bien?');
            if (h.cerradoEseDia) limpiar('fecha', 'hora'); else limpiar('hora');
          }
        } catch (e) { /* se comprobará en Verificar disponibilidad */ }
      }
    }
  }
}

if (correccionFechaHora) {
  return [{ json: {
    ...datos,
    contexto: contextoSalida,
    intencion: 'reserva',
    accionReserva: 'continuar',
    datosReservaEnCurso: datosMergeados,
    mensajeRespuesta: correccionFechaHora
  }}];
}

if (parsed && parsed.accion === 'crear_reserva') {
  return [{ json: {
    ...datos,
    contexto: contextoSalida,
    intencion: 'reserva',
    accionReserva: 'crear',
    datosReservaNueva: { ...datosMergeados, accion: 'crear_reserva' },
    datosReservaEnCurso: datosMergeados,
    mensajeRespuesta: parsed.mensaje || null
  }}];
} else if (parsed && parsed.accion === 'cancelar') {
  return [{ json: {
    ...datos,
    contexto: contextoSalida,
    intencion: 'general',
    accionReserva: 'cancelar',
    datosReservaEnCurso: {},
    mensajeRespuesta: parsed.mensaje || 'De acuerdo, hemos cancelado el proceso de reserva. Hay algo mas en lo que pueda ayudarte?'
  }}];
} else {
  return [{ json: {
    ...datos,
    contexto: contextoSalida,
    intencion: 'reserva',
    accionReserva: 'continuar',
    datosReservaEnCurso: datosMergeados,
    mensajeRespuesta: (parsed?.mensaje || '').trim() || 'Perdona, no te he entendido bien. ¿Me lo repites?'
  }}];
}

// Prepara los datos para guardar en Supabase y para enviar WhatsApp
// --- S6: el teléfono de WhatsApp del cliente nunca va a la IA ----------------
// Se tapa en el historial y en el último mensaje del bot (el resumen de
// reserva o de pedido lleva "📞 Teléfono: …") antes de montar cualquier
// prompt, y también al guardarlos en la sesión.
function taparTelefono(texto, telefono) {
  let t = String(texto == null ? '' : texto);
  const cifras = String(telefono || '').replace(/\D/g, '').replace(/^00/, '');
  if (cifras.length >= 6) {
    const variantes = [cifras];
    if (/^34[6789]\d{8}$/.test(cifras)) variantes.push(cifras.slice(2));
    for (const v of variantes) {
      // Admite un + delante y espacios, puntos o guiones entre cifras.
      t = t.replace(new RegExp('\\+?' + v.split('').join('[\\s.\\-]?'), 'g'), '[tu número]');
    }
  }
  return t.replace(/(📞[^\n:]*:\**\s*)[^\n]*/g, '$1[tu número]');
}
function contextoSinTelefono(ctx, telefono) {
  if (!ctx || typeof ctx !== 'object') return ctx;
  return {
    ...ctx,
    ultimo_mensaje_bot: ctx.ultimo_mensaje_bot == null ? ctx.ultimo_mensaje_bot : taparTelefono(ctx.ultimo_mensaje_bot, telefono),
    historial: Array.isArray(ctx.historial)
      ? ctx.historial.map(m => ({ ...m, texto: taparTelefono(m && m.texto, telefono) }))
      : ctx.historial
  };
}
// --- Fin de S6 -----------------------------------------------------------------
const d = $json;

let telefono = d.telefono || null;
let restaurant_id = d.restaurant_id || null;
let restaurant_nombre = d.restaurant_nombre || null;
let mensajeRespuesta = d.mensajeRespuesta || 'Hola! En que puedo ayudarte?';
let intencion = d.intencion || 'general';
let datosReservaEnCurso = d.datosReservaEnCurso || {};
let datosPedidoEnCurso = d.datosPedidoEnCurso || {};
let contexto = d.contexto || {};
let accionReserva = d.accionReserva || null;
let accionPedido = d.accionPedido || null;

// Si llegamos desde Crear reserva Supabase sin que telefono venga en el nivel
// superior por algún motivo, recuperar del propio nodo (fallback defensivo)
if (!telefono) {
  try {
    const crearNode = $('Crear reserva Supabase').item.json;
    if (crearNode.telefono) {
      telefono = crearNode.telefono;
      restaurant_id = crearNode.restaurant_id;
      restaurant_nombre = crearNode.restaurant_nombre;
      mensajeRespuesta = crearNode.mensajeRespuesta || mensajeRespuesta;
      intencion = crearNode.intencion || intencion;
      datosReservaEnCurso = crearNode.datosReservaEnCurso || {};
      contexto = crearNode.contexto || {};
      accionReserva = null;
    }
  } catch(e) {}
}

// Parsear contexto actual
let contextoActual = contexto;
if (typeof contextoActual === 'string') {
  try { contextoActual = JSON.parse(contextoActual); } catch(e) { contextoActual = {}; }
}
if (!contextoActual || typeof contextoActual !== 'object') {
  contextoActual = {};
}

// Determinar estado
let estadoGuardar = intencion || contextoActual.ultima_intencion || 'general';
if (accionReserva === 'pendiente_confirmacion') estadoGuardar = 'pendiente_confirmacion';
if (accionPedido === 'confirmar' || accionPedido === 'pedir_confirmacion') estadoGuardar = 'pendiente_confirmacion_pedido';
// Anular / cambiar una reserva ya hecha: esperando el "sí" del cliente.
if (d.estadoSesion) estadoGuardar = d.estadoSesion;

// Historial de la conversación (últimos mensajes de cada lado) para que el
// modelo entienda referencias a mensajes anteriores ("mejor la merluza en
// vez del calamar", "lo de antes"). Cada mensaje se recorta: el primero
// suele llevar la carta completa.
const MAX_MENSAJES_HISTORIAL = 10;
const recortar = (t, max = 400) => (t && t.length > max ? t.slice(0, max) + '…' : t);
let mensajeCliente = null;
try { mensajeCliente = $('Extraer mensaje y contexto').first().json.mensajeTexto || null; } catch(e) {}
// Se guarda con el teléfono del cliente tapado (S6): el historial y el
// último mensaje del bot se mandan a la IA en los turnos siguientes.
const historial = [
  ...(Array.isArray(contextoActual.historial) ? contextoActual.historial : []),
  ...(mensajeCliente ? [{ de: 'cliente', texto: recortar(mensajeCliente) }] : []),
  { de: 'restaurante', texto: recortar(mensajeRespuesta) }
].slice(-MAX_MENSAJES_HISTORIAL).map(m => ({ ...m, texto: taparTelefono(m.texto, telefono) }));

const contextoActualizado = {
  ...contextoActual,
  ultima_intencion: intencion || contextoActual.ultima_intencion || 'general',
  estado: estadoGuardar,
  datos_reserva: datosReservaEnCurso || contextoActual.datos_reserva || {},
  datos_pedido: datosPedidoEnCurso || contextoActual.datos_pedido || {},
  // Último mensaje enviado al cliente: los prompts lo usan para interpretar
  // respuestas cortas ("no", "sí") que solas no tienen sentido.
  ultimo_mensaje_bot: taparTelefono(mensajeRespuesta, telefono),
  historial
};

return [{ json: {
  telefono,
  restaurant_id,
  restaurant_nombre,
  mensajeRespuesta,
  contextoJson: JSON.stringify(contextoActualizado)
}}];

// Crea la reserva llamando a fn_reserva_whatsapp_crear, que vuelve a
// comprobar disponibilidad bajo bloqueo justo antes de insertar — cierra
// el hueco de tiempo entre "te pregunto si confirmas" y "el cliente
// responde sí", durante el cual la mesa se podría haber ocupado por
// otra vía. Si eso pasa, busca horas alternativas reales (igual que
// "Verificar disponibilidad" en el primer rechazo) en vez de dejar al
// cliente preguntando a ciegas — el modelo de conversación nunca tiene
// acceso a disponibilidad real, así que si no se la damos aquí, solo
// puede decir "no lo sé".
const d = $json;
const r = d.datosReservaNueva;

const helpers = this.helpers;
// --- Comunes del agente (revisión 1a, docs/specs/2026-11-13-agente-whatsapp-revision.md)
// Supabase con reintentos. Devuelve { ok, status, body }: reintenta los
// fallos de red y los 5xx; un 4xx (datos no válidos, validación de la BD) se
// devuelve sin reintentar. Si sigue fallando, lanza el último error.
async function llamarSupabase(helpers, metodo, ruta, cuerpo, intentos = 3) {
  let ultimoError = null;
  for (let i = 0; i < intentos; i++) {
    try {
      const r = await helpers.httpRequest({
        method: metodo,
        url: `${$env.SUPABASE_URL}${ruta}`,
        headers: {
          'apikey': $env.SUPABASE_SERVICE_ROLE_KEY,
          'Authorization': 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY,
          'Content-Type': 'application/json'
        },
        body: cuerpo,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
      });
      const status = Number(r?.statusCode || 0);
      if (status >= 200 && status < 300) return { ok: true, status, body: r.body };
      if (status >= 400 && status < 500) return { ok: false, status, body: r.body };
      ultimoError = new Error(`Supabase respondió ${status}`);
    } catch (e) {
      ultimoError = e;
    }
    if (i < intentos - 1) {
      try { await new Promise(res => setTimeout(res, 700 * (i + 1))); } catch (e) { /* sin espera */ }
    }
  }
  throw ultimoError || new Error('Supabase no responde');
}

// Registra un aviso en agente_errores (fn_agente_registrar_error). Nunca
// lanza: si no se puede registrar, el flujo sigue y el cliente recibe su
// respuesta. Si falla el registro con detalle, se intenta una sola vez el
// aviso mínimo 'registro_fallido' (sin reintentos en cadena). En el detalle
// nunca van claves ni la conversación.
async function registrarFallo(helpers, base, tipo, paso, error, extra = {}) {
  const texto = String((error && (error.message || error.description)) || error || '').slice(0, 500);
  let ejecucion = null;
  try { ejecucion = $execution.id; } catch (e) { /* sin id */ }
  try {
    const r = await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: (base && base.restaurant_id) || null,
      p_telefono: (base && base.telefono) || null,
      p_tipo: tipo,
      p_paso: paso,
      p_detalle: { error: texto, ejecucion, ...extra }
    }, 2);
    if (r.ok) return true;
  } catch (e) { /* sigue */ }
  try {
    await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: null, p_telefono: null, p_tipo: 'registro_fallido', p_paso: paso,
      p_detalle: { tipo_original: tipo, ejecucion }
    }, 1);
  } catch (e) { /* sin registro */ }
  return false;
}

const MENSAJE_PROBLEMA_TECNICO = 'Perdona, ahora mismo tengo un problema técnico. ¿Me lo repites en un momento?';
// --- Fin de comunes ----------------------------------------------------------
const SERVICE_ROLE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const SUPABASE_URL = $env.SUPABASE_URL;

function getDuracion(personas) {
  if (personas <= 2) return 90;
  if (personas <= 4) return 120;
  if (personas <= 8) return 150;
  return 180;
}
const duracion = d.duracion_minutos || getDuracion(r.personas);

// --- Hora de España y horario de reservas --------------------------------
const DIAS = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const DIAS_TEXTO = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
// Antelación mínima para reservar en el mismo día.
const MARGEN_RESERVA_MIN = 15;

// Devuelve { fecha: 'YYYY-MM-DD', dia: 0-6 (0 = domingo), min: minutos desde
// la medianoche } en hora de España. NUNCA sumar un desfase fijo a UTC:
// España cambia de hora dos veces al año.
function ahoraMadrid(instante = new Date()) {
  try {
    const partes = {};
    new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
      weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
    }).formatToParts(instante).forEach(p => { partes[p.type] = p.value; });
    const dia = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(partes.weekday);
    const min = Number(partes.hour) * 60 + Number(partes.minute);
    if (dia >= 0 && min >= 0 && min < 1440 && partes.year) {
      return { fecha: `${partes.year}-${partes.month}-${partes.day}`, dia, min };
    }
  } catch (e) { /* sin Intl: regla de la UE */ }
  const anio = instante.getUTCFullYear();
  const ultimoDomingo01UTC = mes => {
    const d = new Date(Date.UTC(anio, mes + 1, 0, 1)); // último día del mes, 01:00 UTC
    d.setUTCDate(d.getUTCDate() - d.getUTCDay());
    return d.getTime();
  };
  const verano = instante.getTime() >= ultimoDomingo01UTC(2) && instante.getTime() < ultimoDomingo01UTC(9);
  const local = new Date(instante.getTime() + (verano ? 2 : 1) * 3600000);
  return {
    fecha: local.toISOString().slice(0, 10),
    dia: local.getUTCDay(),
    min: local.getUTCHours() * 60 + local.getUTCMinutes()
  };
}

function aHHMM(min) {
  const m = ((min % 1440) + 1440) % 1440;
  return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
}

function aMin(hhmm) {
  const [h, m] = String(hhmm).split(':').map(Number);
  return h * 60 + (m || 0);
}

function esFechaValida(f) {
  return /^\d{4}-\d{2}-\d{2}$/.test(f || '') && !isNaN(new Date(f + 'T12:00:00Z').getTime());
}

function esHoraValida(h) {
  const m = String(h || '').match(/^(\d{1,2}):(\d{2})$/);
  return !!m && Number(m[1]) <= 23 && Number(m[2]) <= 59;
}

// Día de la semana (0 = domingo) de una fecha de calendario 'YYYY-MM-DD',
// sin pasar por ninguna zona horaria (algoritmo de Sakamoto).
function diaDeFecha(fecha) {
  let [a, m, d] = fecha.split('-').map(Number);
  if (m < 3) a -= 1;
  return (a + Math.floor(a / 4) - Math.floor(a / 100) + Math.floor(a / 400) + [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4][m - 1] + d) % 7;
}

function fechaLarga(fecha) {
  try {
    return new Date(fecha + 'T12:00:00Z').toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC' });
  } catch (e) { return fecha; }
}

function franjasDeDia(config, dia) {
  const h = config?.horario?.[DIAS[dia]];
  if (!h || !h.abierto) return [];
  const out = [];
  [[h.apertura, h.cierre], [h.apertura2, h.cierre2]].forEach(([a, c]) => {
    if (!a || !c) return;
    const inicio = aMin(a);
    let fin = aMin(c);
    if (fin <= inicio) fin += 1440;
    out.push({ inicio, fin, texto: `${a}-${c}` });
  });
  return out;
}

// ¿Está abierto el restaurante a esa hora de esa fecha? Una hora de
// madrugada (00:15) también vale si cae en la franja del día anterior que
// cruza la medianoche (viernes 20:00-00:30 → sábado 00:15).
// Última reserva: config.reservas_minutos_antes_cierre minutos antes del
// cierre de cada franja (60 por defecto; 0 = hasta el cierre). Se configura
// en el panel, en Configuración > Horarios de apertura.
const MINUTOS_ANTES_CIERRE_POR_DEFECTO = 60;
function minutosAntesCierre(config) {
  const v = Number(config?.reservas_minutos_antes_cierre);
  return Number.isFinite(v) && v >= 0 ? v : MINUTOS_ANTES_CIERRE_POR_DEFECTO;
}

function horarioReserva(config, fecha, hora) {
  // Sin horario configurado no se comprueba (igual que en takeaway y en la
  // reserva web): antes se respondía "cerrado" todos los días.
  if (!config?.horario) return { disponible: true };
  const dia = diaDeFecha(fecha);
  const m = aMin(hora);
  const hoy = franjasDeDia(config, dia);
  const ayer = franjasDeDia(config, (dia + 6) % 7);
  // Último minuto en que se admite empezar una reserva en la franja (con 0
  // de margen, cualquier minuto antes del cierre).
  const margen = minutosAntesCierre(config);
  const ultima = f => f.fin - Math.max(margen, 1);
  if (hoy.some(f => m >= f.inicio && m <= ultima(f))
      || ayer.some(f => f.fin > 1440 && m + 1440 <= ultima(f))) {
    return { disponible: true };
  }
  // Dentro del horario pero pasada la hora de la última reserva.
  const tarde = hoy.find(f => m >= f.inicio && m < f.fin)
    || ayer.find(f => f.fin > 1440 && m + 1440 < f.fin);
  if (tarde) {
    return { disponible: false, motivo: `Lo sentimos, a las ${hora} ya no admitimos reservas: la última es a las ${aHHMM(tarde.fin - margen)} (cerramos a las ${aHHMM(tarde.fin)}).` };
  }
  if (hoy.length === 0) {
    return { disponible: false, cerradoEseDia: true, motivo: `Lo sentimos, el restaurante está cerrado el ${DIAS_TEXTO[dia]}.` };
  }
  return { disponible: false, motivo: `Lo sentimos, el restaurante no está abierto a las ${hora}. Nuestro horario ese día es ${hoy.map(f => f.texto).join(' y ')}.` };
}

// Fecha/hora ya pasadas (en hora de España). Devuelve null si está bien, o
// { motivo, limpiar } con los campos que hay que volver a pedir.
function reservaEnPasado(fecha, hora, ahora) {
  if (!esFechaValida(fecha)) return null;
  if (fecha < ahora.fecha) {
    return { motivo: `Esa fecha ya ha pasado (hoy es ${fechaLarga(ahora.fecha)}). ¿Para qué día quieres la reserva?`, limpiar: ['fecha', 'hora'] };
  }
  if (fecha === ahora.fecha && esHoraValida(hora) && aMin(hora) <= ahora.min) {
    return { motivo: `Las ${hora} de hoy ya han pasado (ahora son las ${aHHMM(ahora.min)}). ¿A qué hora quieres la reserva? Para hoy, como pronto a las ${aHHMM(Math.ceil((ahora.min + MARGEN_RESERVA_MIN) / 5) * 5)}.`, limpiar: ['hora'] };
  }
  if (fecha === ahora.fecha && esHoraValida(hora) && aMin(hora) < ahora.min + MARGEN_RESERVA_MIN) {
    return { motivo: `Para reservar hoy necesitamos al menos ${MARGEN_RESERVA_MIN} minutos de antelación (ahora son las ${aHHMM(ahora.min)}). ¿Te viene bien a partir de las ${aHHMM(Math.ceil((ahora.min + MARGEN_RESERVA_MIN) / 5) * 5)}?`, limpiar: ['hora'] };
  }
  return null;
}
// ---------------------------------------------------------------------------

// Entre el "¿confirmas?" y el "sí" pueden pasar minutos: si la hora ya ha
// pasado, no se crea la reserva.
const pasado = reservaEnPasado(r.fecha, r.hora, ahoraMadrid());
if (pasado) {
  const datosLimpios = { ...r };
  pasado.limpiar.forEach(c => { datosLimpios[c] = null; });
  return [{ json: {
    ...d,
    disponibilidad: false,
    accionReserva: 'continuar',
    datosReservaEnCurso: datosLimpios,
    mensajeRespuesta: pasado.motivo
  }}];
}

const notasCombinadas = [
  r.otras_preferencias,
  r.telefono_contacto ? `Tel. contacto: ${r.telefono_contacto}` : null
].filter(Boolean).join(' | ') || null;

// Sin mesa (alguien se adelantó mientras el cliente confirmaba): se buscan
// alternativas reales, como antes.
async function responderSinMesa() {
  // La función SQL avisa con un error claro si, bajo bloqueo, ya no hay
  // mesa (alguien se adelantó mientras el cliente confirmaba). No
  // fingimos una reserva que no llegó a crearse — buscamos alternativas
  // reales para no dejar al cliente sin opciones.
  async function verificarHorario(config, fecha, hora) {
    return horarioReserva(config, fecha, hora).disponible;
  }

  async function hayMesa(fecha, hora, personas, zona, dur) {
    try {
      return await helpers.httpRequest({
        method: 'POST',
        url: `${SUPABASE_URL}/rest/v1/rpc/fn_reserva_hay_mesa`,
        headers: { 'apikey': SERVICE_ROLE_KEY, 'Authorization': 'Bearer ' + SERVICE_ROLE_KEY, 'Content-Type': 'application/json' },
        body: { p_restaurant_id: d.restaurant_id, p_fecha: fecha, p_hora: hora, p_personas: personas, p_zona: zona || null, p_duracion_minutos: dur },
        json: true,
      });
    } catch (e2) {
      return false;
    }
  }

  let alternativas = [];
  try {
    const restData = await helpers.httpRequest({
      method: 'GET',
      url: `${SUPABASE_URL}/rest/v1/restaurants?id=eq.${d.restaurant_id}&select=config`,
      headers: { 'apikey': SERVICE_ROLE_KEY, 'Authorization': 'Bearer ' + SERVICE_ROLE_KEY },
      json: true,
    });
    const config = restData[0]?.config || {};

    const [h, m] = r.hora.split(':').map(Number);
    const horaMin = h * 60 + m;

    for (let delta = -180; delta <= 180; delta += 30) {
      if (delta === 0) continue;
      const nuevoMin = horaMin + delta;
      if (nuevoMin < 0 || nuevoMin >= 24*60) continue;
      const nH = Math.floor(nuevoMin / 60).toString().padStart(2, '0');
      const nM = (nuevoMin % 60).toString().padStart(2, '0');
      const nuevaHora = `${nH}:${nM}`;

      if (reservaEnPasado(r.fecha, nuevaHora, ahoraMadrid())) continue;
      if (!(await verificarHorario(config, r.fecha, nuevaHora))) continue;
      if (await hayMesa(r.fecha, nuevaHora, r.personas, r.zona, duracion)) {
        alternativas.push(nuevaHora);
        if (alternativas.length >= 3) break;
      }
    }
  } catch (e3) { /* si falla la búsqueda de alternativas, seguimos sin ellas */ }

  let msg = `Uy, justo se ocupó esa mesa mientras confirmabas.`;
  if (alternativas.length > 0) {
    msg += ` Te sugiero estas horas libres ese mismo día: ${alternativas.join(', ')}. ¿Te viene bien alguna?`;
  } else {
    msg += ` Ya no quedan huecos para ese día en esa zona. ¿Probamos otra fecha?`;
  }

  return [{ json: {
    ...d,
    disponibilidad: false,
    accionReserva: 'continuar',
    datosReservaEnCurso: { ...r, hora: null },
    mensajeRespuesta: msg
  }}];
}

function hashCorto(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(36);
}
let claveBase = r.clave_reserva || null;
if (!claveBase) {
  // Sesiones de antes del despliegue, sin clave: la versión de la sesión.
  try {
    const s = $('Combinar con sesión').first().json;
    claveBase = `wa-${s.sesion_id || d.telefono}-${s.sesion_updated_at ? Date.parse(s.sesion_updated_at) : 0}`;
  } catch (e) { claveBase = `wa-${d.telefono}-${Date.now()}`; }
}
const claveReserva = `${claveBase}-${hashCorto(JSON.stringify([r.nombre, r.fecha, r.hora, r.personas, r.zona || null]))}`;

let respuestaCrear;
try {
  respuestaCrear = await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_reserva_whatsapp_crear', {
    p_restaurant_id: d.restaurant_id,
      p_nombre: r.nombre,
      p_telefono: d.telefono,
      p_fecha: r.fecha,
      p_hora: r.hora,
      p_personas: r.personas,
      p_zona: r.zona || 'sin preferencia',
      p_notas: notasCombinadas,
      p_duracion_minutos: duracion,
    // Misma clave = misma reserva: un "sí" repetido (p. ej. si no llegó la
    // confirmación) no crea otra. Lleva el hash de los datos por si cambiaron.
    p_clave: claveReserva
  });
} catch (e) {
  // Fallo técnico (tras los reintentos): mensaje honesto, aviso
  // reserva_no_creada y se sigue esperando el "sí" para poder reintentar.
  await registrarFallo(helpers, d, 'reserva_no_creada', 'Crear reserva Supabase', e);
  return [{ json: { ...d, disponibilidad: false, accionReserva: 'pendiente_confirmacion', datosReservaEnCurso: r, mensajeRespuesta: MENSAJE_PROBLEMA_TECNICO } }];
}

if (!respuestaCrear.ok) {
  // P0001 = validación de fn_reserva_whatsapp_crear, con un texto pensado
  // para el cliente (fecha pasada, antelación, horario, personas, textos o
  // mesa ocupada). Cualquier otro error es técnico (E8: antes todo se
  // explicaba como "justo se ocupó esa mesa").
  const motivoBD = respuestaCrear.body?.code === 'P0001' ? String(respuestaCrear.body?.message || '').trim() : '';
  if (!motivoBD) {
    await registrarFallo(helpers, d, 'reserva_no_creada', 'Crear reserva Supabase',
      `HTTP ${respuestaCrear.status}: ${JSON.stringify(respuestaCrear.body || '').slice(0, 300)}`);
    return [{ json: { ...d, disponibilidad: false, accionReserva: 'pendiente_confirmacion', datosReservaEnCurso: r, mensajeRespuesta: MENSAJE_PROBLEMA_TECNICO } }];
  }
  if (/^Ya no hay disponibilidad/i.test(motivoBD)) return await responderSinMesa();
  const campo = /personas/i.test(motivoBD) ? 'personas' : /nombre/i.test(motivoBD) ? 'nombre'
    : /notas/i.test(motivoBD) ? 'otras_preferencias' : /fecha y hora|fecha o la hora/i.test(motivoBD) ? 'fecha' : 'hora';
  const datosLimpios = { ...r, [campo]: null };
  if (campo === 'fecha') datosLimpios.hora = null;
  return [{ json: { ...d, disponibilidad: false, accionReserva: 'continuar', datosReservaEnCurso: datosLimpios, mensajeRespuesta: motivoBD } }];
}

let fechaFormateada = r.fecha;
try {
  const fechaObj = new Date(r.fecha + 'T12:00:00');
  fechaFormateada = fechaObj.toLocaleDateString('es-ES', {weekday:'long', day:'numeric', month:'long'});
} catch(e) {}

const zonaTexto = r.zona && r.zona !== 'sin preferencia' ? r.zona.charAt(0).toUpperCase() + r.zona.slice(1) : null;

// Si la reserva ya existía ("sí" repetido), se repiten los datos sin otro ✅.
let mensajeConfirmacion = respuestaCrear.body && respuestaCrear.body.ya_existia
  ? `Tu reserva en ${d.restaurant_nombre} ya está registrada, no la he duplicado:\n\n`
  : `✅ *Reserva confirmada en ${d.restaurant_nombre}!*\n\n`;
mensajeConfirmacion += `📅 *Fecha:* ${fechaFormateada}\n`;
mensajeConfirmacion += `🕐 *Hora:* ${r.hora}\n`;
mensajeConfirmacion += `👥 *Personas:* ${r.personas}\n`;
mensajeConfirmacion += `👤 *Nombre:* ${r.nombre}\n`;
if (zonaTexto) mensajeConfirmacion += `📍 *Zona:* ${zonaTexto}\n`;
if (r.otras_preferencias) mensajeConfirmacion += `📝 *Preferencias:* ${r.otras_preferencias}\n`;
mensajeConfirmacion += `\nTe esperamos con mucho gusto. 🍽 ¡Hasta pronto!`;

return [{ json: {
  telefono: d.telefono,
  restaurant_id: d.restaurant_id,
  restaurant_nombre: d.restaurant_nombre,
  mensajeRespuesta: mensajeConfirmacion,
  intencion: 'general',
  datosReservaEnCurso: {},
  contexto: d.contexto,
  reserva_nombre: r.nombre,
  reserva_fecha: r.fecha,
  reserva_hora: r.hora,
  reserva_personas: r.personas,
  reserva_zona: r.zona || 'sin preferencia',
  reserva_notas: notasCombinadas,
  reserva_duracion: duracion
}}];

// Verifica disponibilidad real en Supabase, vía fn_reserva_hay_mesa —
// comprueba capacidad de cada mesa (no solo cantidad) y también las
// mesas ocupadas ahora mismo por clientes sin reserva (table_sessions),
// no solo otras reservas. Esta comprobación es INFORMATIVA: decide si
// se le pregunta "¿confirmas?" al cliente o se buscan alternativas. La
// comprobación que de verdad cuenta corre otra vez, bajo bloqueo, justo
// antes de insertar — en "Crear reserva Supabase" vía
// fn_reserva_whatsapp_crear — para que no quede un hueco de tiempo
// entre preguntar y que el cliente responda "sí".
const d = $json;
const r = d.datosReservaNueva;

let SERVICE_ROLE_KEY;
let SUPABASE_URL;
const helpers = this.helpers;
// --- Comunes del agente (revisión 1a, docs/specs/2026-11-13-agente-whatsapp-revision.md)
// Supabase con reintentos. Devuelve { ok, status, body }: reintenta los
// fallos de red y los 5xx; un 4xx (datos no válidos, validación de la BD) se
// devuelve sin reintentar. Si sigue fallando, lanza el último error.
async function llamarSupabase(helpers, metodo, ruta, cuerpo, intentos = 3) {
  let ultimoError = null;
  for (let i = 0; i < intentos; i++) {
    try {
      const r = await helpers.httpRequest({
        method: metodo,
        url: `${$env.SUPABASE_URL}${ruta}`,
        headers: {
          'apikey': $env.SUPABASE_SERVICE_ROLE_KEY,
          'Authorization': 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY,
          'Content-Type': 'application/json'
        },
        body: cuerpo,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
      });
      const status = Number(r?.statusCode || 0);
      if (status >= 200 && status < 300) return { ok: true, status, body: r.body };
      if (status >= 400 && status < 500) return { ok: false, status, body: r.body };
      ultimoError = new Error(`Supabase respondió ${status}`);
    } catch (e) {
      ultimoError = e;
    }
    if (i < intentos - 1) {
      try { await new Promise(res => setTimeout(res, 700 * (i + 1))); } catch (e) { /* sin espera */ }
    }
  }
  throw ultimoError || new Error('Supabase no responde');
}

// Registra un aviso en agente_errores (fn_agente_registrar_error). Nunca
// lanza: si no se puede registrar, el flujo sigue y el cliente recibe su
// respuesta. Si falla el registro con detalle, se intenta una sola vez el
// aviso mínimo 'registro_fallido' (sin reintentos en cadena). En el detalle
// nunca van claves ni la conversación.
async function registrarFallo(helpers, base, tipo, paso, error, extra = {}) {
  const texto = String((error && (error.message || error.description)) || error || '').slice(0, 500);
  let ejecucion = null;
  try { ejecucion = $execution.id; } catch (e) { /* sin id */ }
  try {
    const r = await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: (base && base.restaurant_id) || null,
      p_telefono: (base && base.telefono) || null,
      p_tipo: tipo,
      p_paso: paso,
      p_detalle: { error: texto, ejecucion, ...extra }
    }, 2);
    if (r.ok) return true;
  } catch (e) { /* sigue */ }
  try {
    await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: null, p_telefono: null, p_tipo: 'registro_fallido', p_paso: paso,
      p_detalle: { tipo_original: tipo, ejecucion }
    }, 1);
  } catch (e) { /* sin registro */ }
  return false;
}

const MENSAJE_PROBLEMA_TECNICO = 'Perdona, ahora mismo tengo un problema técnico. ¿Me lo repites en un momento?';
// --- Fin de comunes ----------------------------------------------------------

function getDuracion(personas) {
  if (personas <= 2) return 90;
  if (personas <= 4) return 120;
  if (personas <= 8) return 150;
  return 180;
}

// --- Hora de España y horario de reservas --------------------------------
const DIAS = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const DIAS_TEXTO = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
// Antelación mínima para reservar en el mismo día.
const MARGEN_RESERVA_MIN = 15;

// Devuelve { fecha: 'YYYY-MM-DD', dia: 0-6 (0 = domingo), min: minutos desde
// la medianoche } en hora de España. NUNCA sumar un desfase fijo a UTC:
// España cambia de hora dos veces al año.
function ahoraMadrid(instante = new Date()) {
  try {
    const partes = {};
    new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
      weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
    }).formatToParts(instante).forEach(p => { partes[p.type] = p.value; });
    const dia = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(partes.weekday);
    const min = Number(partes.hour) * 60 + Number(partes.minute);
    if (dia >= 0 && min >= 0 && min < 1440 && partes.year) {
      return { fecha: `${partes.year}-${partes.month}-${partes.day}`, dia, min };
    }
  } catch (e) { /* sin Intl: regla de la UE */ }
  const anio = instante.getUTCFullYear();
  const ultimoDomingo01UTC = mes => {
    const d = new Date(Date.UTC(anio, mes + 1, 0, 1)); // último día del mes, 01:00 UTC
    d.setUTCDate(d.getUTCDate() - d.getUTCDay());
    return d.getTime();
  };
  const verano = instante.getTime() >= ultimoDomingo01UTC(2) && instante.getTime() < ultimoDomingo01UTC(9);
  const local = new Date(instante.getTime() + (verano ? 2 : 1) * 3600000);
  return {
    fecha: local.toISOString().slice(0, 10),
    dia: local.getUTCDay(),
    min: local.getUTCHours() * 60 + local.getUTCMinutes()
  };
}

function aHHMM(min) {
  const m = ((min % 1440) + 1440) % 1440;
  return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
}

function aMin(hhmm) {
  const [h, m] = String(hhmm).split(':').map(Number);
  return h * 60 + (m || 0);
}

function esFechaValida(f) {
  return /^\d{4}-\d{2}-\d{2}$/.test(f || '') && !isNaN(new Date(f + 'T12:00:00Z').getTime());
}

function esHoraValida(h) {
  const m = String(h || '').match(/^(\d{1,2}):(\d{2})$/);
  return !!m && Number(m[1]) <= 23 && Number(m[2]) <= 59;
}

// Día de la semana (0 = domingo) de una fecha de calendario 'YYYY-MM-DD',
// sin pasar por ninguna zona horaria (algoritmo de Sakamoto).
function diaDeFecha(fecha) {
  let [a, m, d] = fecha.split('-').map(Number);
  if (m < 3) a -= 1;
  return (a + Math.floor(a / 4) - Math.floor(a / 100) + Math.floor(a / 400) + [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4][m - 1] + d) % 7;
}

function fechaLarga(fecha) {
  try {
    return new Date(fecha + 'T12:00:00Z').toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC' });
  } catch (e) { return fecha; }
}

function franjasDeDia(config, dia) {
  const h = config?.horario?.[DIAS[dia]];
  if (!h || !h.abierto) return [];
  const out = [];
  [[h.apertura, h.cierre], [h.apertura2, h.cierre2]].forEach(([a, c]) => {
    if (!a || !c) return;
    const inicio = aMin(a);
    let fin = aMin(c);
    if (fin <= inicio) fin += 1440;
    out.push({ inicio, fin, texto: `${a}-${c}` });
  });
  return out;
}

// ¿Está abierto el restaurante a esa hora de esa fecha? Una hora de
// madrugada (00:15) también vale si cae en la franja del día anterior que
// cruza la medianoche (viernes 20:00-00:30 → sábado 00:15).
// Última reserva: config.reservas_minutos_antes_cierre minutos antes del
// cierre de cada franja (60 por defecto; 0 = hasta el cierre). Se configura
// en el panel, en Configuración > Horarios de apertura.
const MINUTOS_ANTES_CIERRE_POR_DEFECTO = 60;
function minutosAntesCierre(config) {
  const v = Number(config?.reservas_minutos_antes_cierre);
  return Number.isFinite(v) && v >= 0 ? v : MINUTOS_ANTES_CIERRE_POR_DEFECTO;
}

function horarioReserva(config, fecha, hora) {
  // Sin horario configurado no se comprueba (igual que en takeaway y en la
  // reserva web): antes se respondía "cerrado" todos los días.
  if (!config?.horario) return { disponible: true };
  const dia = diaDeFecha(fecha);
  const m = aMin(hora);
  const hoy = franjasDeDia(config, dia);
  const ayer = franjasDeDia(config, (dia + 6) % 7);
  // Último minuto en que se admite empezar una reserva en la franja (con 0
  // de margen, cualquier minuto antes del cierre).
  const margen = minutosAntesCierre(config);
  const ultima = f => f.fin - Math.max(margen, 1);
  if (hoy.some(f => m >= f.inicio && m <= ultima(f))
      || ayer.some(f => f.fin > 1440 && m + 1440 <= ultima(f))) {
    return { disponible: true };
  }
  // Dentro del horario pero pasada la hora de la última reserva.
  const tarde = hoy.find(f => m >= f.inicio && m < f.fin)
    || ayer.find(f => f.fin > 1440 && m + 1440 < f.fin);
  if (tarde) {
    return { disponible: false, motivo: `Lo sentimos, a las ${hora} ya no admitimos reservas: la última es a las ${aHHMM(tarde.fin - margen)} (cerramos a las ${aHHMM(tarde.fin)}).` };
  }
  if (hoy.length === 0) {
    return { disponible: false, cerradoEseDia: true, motivo: `Lo sentimos, el restaurante está cerrado el ${DIAS_TEXTO[dia]}.` };
  }
  return { disponible: false, motivo: `Lo sentimos, el restaurante no está abierto a las ${hora}. Nuestro horario ese día es ${hoy.map(f => f.texto).join(' y ')}.` };
}

// Fecha/hora ya pasadas (en hora de España). Devuelve null si está bien, o
// { motivo, limpiar } con los campos que hay que volver a pedir.
function reservaEnPasado(fecha, hora, ahora) {
  if (!esFechaValida(fecha)) return null;
  if (fecha < ahora.fecha) {
    return { motivo: `Esa fecha ya ha pasado (hoy es ${fechaLarga(ahora.fecha)}). ¿Para qué día quieres la reserva?`, limpiar: ['fecha', 'hora'] };
  }
  if (fecha === ahora.fecha && esHoraValida(hora) && aMin(hora) <= ahora.min) {
    return { motivo: `Las ${hora} de hoy ya han pasado (ahora son las ${aHHMM(ahora.min)}). ¿A qué hora quieres la reserva? Para hoy, como pronto a las ${aHHMM(Math.ceil((ahora.min + MARGEN_RESERVA_MIN) / 5) * 5)}.`, limpiar: ['hora'] };
  }
  if (fecha === ahora.fecha && esHoraValida(hora) && aMin(hora) < ahora.min + MARGEN_RESERVA_MIN) {
    return { motivo: `Para reservar hoy necesitamos al menos ${MARGEN_RESERVA_MIN} minutos de antelación (ahora son las ${aHHMM(ahora.min)}). ¿Te viene bien a partir de las ${aHHMM(Math.ceil((ahora.min + MARGEN_RESERVA_MIN) / 5) * 5)}?`, limpiar: ['hora'] };
  }
  return null;
}
// ---------------------------------------------------------------------------

async function verificarHorario(config, fecha, hora) {
  return horarioReserva(config, fecha, hora);
}

// Llama a fn_reserva_hay_mesa — único sitio donde vive el cálculo real,
// compartido con la creación atómica, para no tener la lógica
// duplicada en dos sitios que se puedan desincronizar.
async function hayMesa(restaurantId, fecha, hora, personas, zona, duracion) {
  try {
    return await helpers.httpRequest({
      method: 'POST',
      url: `${SUPABASE_URL}/rest/v1/rpc/fn_reserva_hay_mesa`,
      headers: {
        'apikey': SERVICE_ROLE_KEY,
        'Authorization': 'Bearer ' + SERVICE_ROLE_KEY,
        'Content-Type': 'application/json',
      },
      body: {
        p_restaurant_id: restaurantId,
        p_fecha: fecha,
        p_hora: hora,
        p_personas: personas,
        p_zona: zona || null,
        p_duracion_minutos: duracion,
      },
      json: true,
    });
  } catch (e) {
    // Antes devolvía false ("no hay mesa") ante cualquier fallo: ahora el
    // fallo técnico se explica como tal (catch de abajo).
    throw e;
  }
}

async function buscarAlternativas(restaurantId, fecha, hora, duracion, personas, zona, config) {
  const [h, m] = hora.split(':').map(Number);
  const horaMin = h * 60 + m;
  const alternativas = [];

  for (let delta = -180; delta <= 180; delta += 30) {
    if (delta === 0) continue;
    const nuevoMin = horaMin + delta;
    if (nuevoMin < 0 || nuevoMin >= 24*60) continue;

    const nH = Math.floor(nuevoMin / 60).toString().padStart(2, '0');
    const nM = (nuevoMin % 60).toString().padStart(2, '0');
    const nuevaHora = `${nH}:${nM}`;

    // Para hoy, solo horas que todavía no hayan pasado.
    if (reservaEnPasado(fecha, nuevaHora, ahoraMadrid())) continue;

    const horarioOk = await verificarHorario(config, fecha, nuevaHora);
    if (!horarioOk.disponible) continue;

    const libre = await hayMesa(restaurantId, fecha, nuevaHora, personas, zona, duracion);
    if (libre) {
      alternativas.push(nuevaHora);
      if (alternativas.length >= 3) break;
    }
  }

  return alternativas;
}

try {
  SERVICE_ROLE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
  SUPABASE_URL = $env.SUPABASE_URL;
  if (!SERVICE_ROLE_KEY || !SUPABASE_URL) {
    throw new Error('Faltan las variables de entorno de Supabase.');
  }

  const restData = await helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/restaurants?id=eq.${d.restaurant_id}&select=config`,
    headers: { 'apikey': SERVICE_ROLE_KEY, 'Authorization': 'Bearer ' + SERVICE_ROLE_KEY },
    json: true,
  });
  const config = restData[0]?.config || {};

