Responde con un JSON con esta estructura:
{
  "accion": "continuar" | "confirmar_pedido" | "cancelar",
  "mensaje": "tu respuesta natural al cliente en español",
  "items": [
    {"nombre": "nombre EXACTO del plato", "cantidad": número, "notas": null o "nota del plato (punto de la carne, sin cebolla...)"}
  ],
  "hora_recogida": null o "HH:MM",
  "nombre_cliente": null o "nombre",
  "telefono_cliente": null o "teléfono"
}

"items" es SIEMPRE el pedido COMPLETO tal como queda después de lo que dice el cliente, no solo lo nuevo: si añade, súmalo a lo que había; si quita algo o cambia una cantidad, devuelve la lista ya corregida; si cambia un plato por otro ("cámbiame una de las merluzas por un secreto bien hecho"), resta 1 al primero y añade el segundo con su nota. Si el mensaje no toca los platos, devuelve igualmente la lista completa tal cual.

IMPORTES — MUY IMPORTANTE: en "mensaje" NUNCA escribas precios de los platos del pedido, subtotales ni totales, ni enumeres los platos del pedido: el sistema añade automáticamente el resumen del pedido con los importes correctos cada vez que cambia o el cliente pregunta la cuenta. Tú confirma brevemente lo que has hecho ("Hecho, cambio una merluza por un secreto ibérico bien hecho") y haz la siguiente pregunta. Si el cliente pregunta el precio de un plato concreto de la carta, sí puedes decírselo.

Estilo de "mensaje" (salvo cuando tengas que mostrar la carta completa en el primer mensaje, punto 1): sé breve y natural, como lo escribiría una persona por WhatsApp (2-3 líneas). No repitas cada plato o dato en una lista larga con emojis si ya se lo confirmaste antes.

INSTRUCCIONES:
1. Primera vez → incluye la carta completa en "mensaje":
${cartaTexto}
2. Recoge platos en "items" (siempre la lista completa). "Nada más", "eso es todo" o "ya está" significan que ha terminado de pedir, NO que quiera cancelar: pasa a la hora de recogida.
3. Cuando termine → pregunta hora de recogida (${recogidaTexto}).
4. Pregunta el nombre. NO pidas el teléfono: usamos el de WhatsApp. Solo si el cliente da otro teléfono por su cuenta, guárdalo en "telefono_cliente".
5. Cuando tengas platos, hora y nombre → usa "confirmar_pedido". El sistema le envía al cliente el resumen con el total y le pide confirmación: NO escribas tú el resumen ni el total, ni des el pedido por confirmado.
6. Si ya se le envió el resumen (Estado: pendiente_confirmacion_pedido): si el cliente dice que sí → "confirmar_pedido"; si quiere cambiar algo → aplica el cambio y usa "continuar"; si no quiere el pedido → "cancelar".
7. IMPORTANTE sobre hora_recogida: cada vez que el cliente mencione una hora (aunque esté escrita como pregunta, ej: "23:59hs?", "a las 23:45?", "puede ser a las 8?"), interpretalo SIEMPRE como una propuesta de horario y completá el campo "hora_recogida" con esa hora en formato "HH:MM". Nunca dejes "hora_recogida" en null si el mensaje del cliente contiene una hora, incluso si el formato de la pregunta es ambiguo o incluye "?" o "hs".
8. IMPORTANTE sobre nombres de platos: si el cliente escribe el nombre de un plato con errores de tipeo, abreviado, en minúsculas, o ligeramente distinto al de la carta (ej: "patas bravas" en vez de "Patatas Bravas", "coca cola" en vez de "Coca Cola"), identificá el plato más parecido de la carta de referencia y usá SIEMPRE el nombre EXACTO tal como aparece en la carta al completar el campo "nombre" en el JSON. Solo pedí aclaración si hay ambigüedad real entre dos o más platos distintos, o si el plato definitivamente no existe en la carta.

Carta de referencia:${cartaParaPrompt}

Estado: ${estadoActual}
Pedido en curso: ${JSON.stringify(datosPedido)}${conversacionReciente ? `\n\nConversación reciente con el cliente (la más antigua primero; úsala para entender a qué se refiere, por ejemplo "mejor X en vez de Y" o "lo de antes"; el pedido en curso de arriba manda sobre lo que se dijo aquí):\n${conversacionReciente}` : ''}${ultimoMensajeBot ? `\n\nÚltimo mensaje que enviaste al cliente (su mensaje actual responde a esto): "${ultimoMensajeBot}"` : ''}`;

return [{ json: {
  ...datos,
  contexto,
  datosPedido,
  estadoActual,
  menuItems: items,
  intencion: 'takeaway',
  horarioConfig: horario || null,
  takeawayMinutosAntesCierre: margenCierreTakeaway,
  esquemaRespuesta: ESQUEMA_RESPUESTA_TAKEAWAY,
  systemPromptTakeaway: systemPrompt
}}];

// Procesa la respuesta del modelo para takeaway
// --- Comunes del agente (revisión 1a, docs/specs/2026-11-13-agente-whatsapp-revision.md)
// Supabase con reintentos. Devuelve { ok, status, body }: reintenta los
// fallos de red y los 5xx; un 4xx (datos no válidos, validación de la BD) se
// devuelve sin reintentar. Si sigue fallando, lanza el último error.
async function llamarSupabase(helpers, metodo, ruta, cuerpo, intentos = 3) {
  let ultimoError = null;
  for (let i = 0; i < intentos; i++) {
    try {
      const r = await helpers.httpRequest({
        method: metodo,
        url: `${$env.SUPABASE_URL}${ruta}`,
        headers: {
          'apikey': $env.SUPABASE_SERVICE_ROLE_KEY,
          'Authorization': 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY,
          'Content-Type': 'application/json'
        },
        body: cuerpo,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
      });
      const status = Number(r?.statusCode || 0);
      if (status >= 200 && status < 300) return { ok: true, status, body: r.body };
      if (status >= 400 && status < 500) return { ok: false, status, body: r.body };
      ultimoError = new Error(`Supabase respondió ${status}`);
    } catch (e) {
      ultimoError = e;
    }
    if (i < intentos - 1) {
      try { await new Promise(res => setTimeout(res, 700 * (i + 1))); } catch (e) { /* sin espera */ }
    }
  }
  throw ultimoError || new Error('Supabase no responde');
}

// Registra un aviso en agente_errores (fn_agente_registrar_error). Nunca
// lanza: si no se puede registrar, el flujo sigue y el cliente recibe su
// respuesta. Si falla el registro con detalle, se intenta una sola vez el
// aviso mínimo 'registro_fallido' (sin reintentos en cadena). En el detalle
// nunca van claves ni la conversación.
async function registrarFallo(helpers, base, tipo, paso, error, extra = {}) {
  const texto = String((error && (error.message || error.description)) || error || '').slice(0, 500);
  let ejecucion = null;
  try { ejecucion = $execution.id; } catch (e) { /* sin id */ }
  try {
    const r = await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: (base && base.restaurant_id) || null,
      p_telefono: (base && base.telefono) || null,
      p_tipo: tipo,
      p_paso: paso,
      p_detalle: { error: texto, ejecucion, ...extra }
    }, 2);
    if (r.ok) return true;
  } catch (e) { /* sigue */ }
  try {
    await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: null, p_telefono: null, p_tipo: 'registro_fallido', p_paso: paso,
      p_detalle: { tipo_original: tipo, ejecucion }
    }, 1);
  } catch (e) { /* sin registro */ }
  return false;
}

