// Respuesta del modelo: JSON forzado por el esquema (output_config.format en
// la llamada). Por si acaso, se aísla el objeto JSON aunque venga con texto
// alrededor: nunca se le manda al cliente el texto crudo (el 9 nov salió un
// JSON entero por WhatsApp).
function extraerJSON(texto) {
  const t = String(texto || '').split('`').join('').trim();
  try { return JSON.parse(t); } catch (e) { /* sigue */ }
  const ini = t.indexOf('{'), fin = t.lastIndexOf('}');
  if (ini >= 0 && fin > ini) { try { return JSON.parse(t.slice(ini, fin + 1)); } catch (e) { /* sigue */ } }
  return null;
}
const parsed = extraerJSON(gptText);

// --- Hora de España y franjas de recogida ---------------------------------
// La hora se saca con la zona Europe/Madrid, así cambia sola entre horario
// de verano (UTC+2) e invierno (UTC+1). Antes se sumaban 2 h fijas a UTC y
// en invierno el agente iba una hora adelantada.
const DIAS = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const MARGEN_PREPARACION_MIN = 15;

// Devuelve { fecha: 'YYYY-MM-DD', dia: 0-6 (0 = domingo), min: minutos desde
// la medianoche } en hora de España. NUNCA sumar un desfase fijo a UTC:
// España cambia de hora dos veces al año.
function ahoraMadrid(instante = new Date()) {
  try {
    const partes = {};
    new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
      weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
    }).formatToParts(instante).forEach(p => { partes[p.type] = p.value; });
    const dia = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(partes.weekday);
    const min = Number(partes.hour) * 60 + Number(partes.minute);
    if (dia >= 0 && min >= 0 && min < 1440 && partes.year) {
      return { fecha: `${partes.year}-${partes.month}-${partes.day}`, dia, min };
    }
  } catch (e) { /* sin Intl: regla de la UE */ }
  const anio = instante.getUTCFullYear();
  const ultimoDomingo01UTC = mes => {
    const d = new Date(Date.UTC(anio, mes + 1, 0, 1)); // último día del mes, 01:00 UTC
    d.setUTCDate(d.getUTCDate() - d.getUTCDay());
    return d.getTime();
  };
  const verano = instante.getTime() >= ultimoDomingo01UTC(2) && instante.getTime() < ultimoDomingo01UTC(9);
  const local = new Date(instante.getTime() + (verano ? 2 : 1) * 3600000);
  return {
    fecha: local.toISOString().slice(0, 10),
    dia: local.getUTCDay(),
    min: local.getUTCHours() * 60 + local.getUTCMinutes()
  };
}

function aHHMM(min) {
  const m = ((min % 1440) + 1440) % 1440;
  return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
}

function aMin(hhmm) {
  const [h, m] = String(hhmm).split(':').map(Number);
  return h * 60 + (m || 0);
}

// Franjas en minutos contados desde la medianoche de hoy. Una franja que
// cruza la medianoche (20:00-00:30) termina en 1470. La de ayer que cruza la
// medianoche entra desplazada -1440, para que a las 00:15 siga abierto.
// ultima: la recogida más tardía de la franja (cierre - margenCierre).
function franjasDelDia(horario, dia, desplazamiento, margenCierre = 0) {
  const h = horario?.[DIAS[dia]];
  if (!h || !h.abierto) return [];
  const out = [];
  [[h.apertura, h.cierre], [h.apertura2, h.cierre2]].forEach(([a, c]) => {
    if (!a || !c) return;
    const inicio = aMin(a);
    let fin = aMin(c);
    if (fin <= inicio) fin += 1440;
    out.push({ inicio: inicio + desplazamiento, fin: fin + desplazamiento, ultima: fin - margenCierre + desplazamiento, texto: `${a}-${c}` });
  });
  return out;
}

function franjasVigentes(horario, ahora, margenCierre = 0) {
  const ayer = (ahora.dia + 6) % 7;
  return [
    ...franjasDelDia(horario, ayer, -1440, margenCierre).filter(f => f.fin > ahora.min),
    ...franjasDelDia(horario, ahora.dia, 0, margenCierre)
  ];
}

// Tramos en los que todavía se puede recoger (desde ahora + margen,
// redondeado a 5 min, hasta la última recogida de cada franja).
function tramosDisponibles(franjas, ahoraMin) {
  const minimo = Math.ceil((ahoraMin + MARGEN_PREPARACION_MIN) / 5) * 5;
  return franjas
    .map(f => ({ desde: Math.max(f.inicio, minimo), hasta: f.ultima }))
    .filter(t => t.desde <= t.hasta);
}

function textoTramos(tramos) {
  return tramos.map(t => `entre las ${aHHMM(t.desde)} y las ${aHHMM(t.hasta)}`).join(' o ');
}

// Valida "HH:MM". La hora se interpreta como la próxima vez que llega:
// hoy, o pasada la medianoche si cae en una franja que la cruza.
function validarHoraRecogida(hora, franjas, ahoraMin) {
  const ahoraTxt = aHHMM(ahoraMin);
  const tramos = tramosDisponibles(franjas, ahoraMin);
  if (tramos.length === 0) {
    return { ok: false, sinHorario: true, mensaje: 'Lo siento, por hoy ya no podemos aceptar más pedidos para recoger. ¡Te esperamos otro día!' };
  }
  const match = String(hora || '').match(/^(\d{1,2}):(\d{2})$/);
  if (!match || Number(match[1]) > 23 || Number(match[2]) > 59) {
    return { ok: false, mensaje: `No he entendido la hora. Podemos tenerlo listo ${textoTramos(tramos)}. ¿A qué hora te viene bien?` };
  }
  const m = Number(match[1]) * 60 + Number(match[2]);
  const t = [m, m + 1440].find(x => tramos.some(tr => x >= tr.desde && x <= tr.hasta));
  // diaSiguiente: recogida pasada la medianoche (franja que la cruza).
  if (t !== undefined) return { ok: true, hora: aHHMM(t), diaSiguiente: t >= 1440 };

  // Se distingue entre hora ya pasada, demasiado pronta (no da tiempo a
  // preparar) y fuera del horario, para que el cliente entienda el motivo.
  const enFranja = [m, m + 1440].find(x => franjas.some(f => x >= f.inicio && x <= f.fin));
  const alternativa = `Hoy todavía puedes recogerlo ${textoTramos(tramos)}. ¿A qué hora te viene bien?`;
  const franjaHora = enFranja !== undefined ? franjas.find(f => enFranja >= f.inicio && enFranja <= f.fin) : null;
  let motivo;
  if (enFranja !== undefined && enFranja <= ahoraMin) {
    motivo = `Las ${aHHMM(m)} de hoy ya han pasado (ahora son las ${ahoraTxt}).`;
  } else if (franjaHora && enFranja > franjaHora.ultima) {
    // Abierto, pero pasada la última recogida (takeaway_minutos_antes_cierre).
    motivo = `A las ${aHHMM(m)} ya no aceptamos pedidos para recoger: la última recogida es a las ${aHHMM(franjaHora.ultima)} (cerramos a las ${aHHMM(franjaHora.fin)}).`;
  } else if (enFranja !== undefined) {
    motivo = `A las ${aHHMM(m)} no nos da tiempo a prepararlo: necesitamos al menos ${MARGEN_PREPARACION_MIN} minutos (ahora son las ${ahoraTxt}).`;
  } else if (m < ahoraMin) {
    motivo = `Las ${aHHMM(m)} de hoy ya han pasado (ahora son las ${ahoraTxt}).`;
  } else {
    motivo = `A las ${aHHMM(m)} no estamos abiertos.`;
  }
  return { ok: false, mensaje: `${motivo} ${alternativa}` };
}
// ---------------------------------------------------------------------------

// Respaldo: si el modelo no devolvió hora_recogida, la buscamos en el texto
// del cliente. Solo formatos de hora claros ("22:15", "22h15", "22h",
// "a las 22", "a las 22.15"): un "9.50" suelto puede ser un precio.
function extraerHoraDelTexto(texto) {
  if (!texto) return null;
  const t = texto.toLowerCase();
  let m = t.match(/\b([01]?\d|2[0-3])\s*(?::|h)\s*([0-5]\d)(?!\d)/)
       || t.match(/\ba las\s+([01]?\d|2[0-3])[.:]([0-5]\d)(?!\d)/);
  if (m) return `${m[1].padStart(2, '0')}:${m[2]}`;
  m = t.match(/\ba las\s+([01]?\d|2[0-3])(?![\d.:])(?:\s+y\s+(media|cuarto))?/)
   || t.match(/\b([01]?\d|2[0-3])\s*(?:h|hs)\b/);
  if (m) return `${m[1].padStart(2, '0')}:${m[2] === 'media' ? '30' : m[2] === 'cuarto' ? '15' : '00'}`;
  return null;
}

function normalizarHora(h) {
  const m = String(h || '').trim().match(/^(\d{1,2})[:.hH](\d{2})/);
  return m ? `${m[1].padStart(2, '0')}:${m[2]}` : null;
}

function normalizarTexto(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
}

const pedidoActual = datos.datosPedido || {};
const itemsNuevos = parsed?.items || pedidoActual.items || [];
const itemsCrudos = itemsNuevos.length > 0 ? itemsNuevos : (pedidoActual.items || []);

// El precio de cada plato SIEMPRE se toma de la carta real, nunca de
// lo que haya devuelto el modelo — a veces confunde "precio unitario"
// con "subtotal ya multiplicado por la cantidad", y como el backend
// vuelve a multiplicar por la cantidad al calcular el total, el
// cliente terminaba viendo precios muy por encima de lo real.
// Si el nombre no coincide exacto se prueba sin tildes/mayúsculas y, si
// solo hay un plato que lo contenga, ese. Lo que no está en la carta se
// descarta y se avisa al cliente (antes entraba con el precio inventado
// por el modelo y sin menu_item_id).
const menuItemsReal = datos.menuItems || [];
const noEncontrados = [];
const itemsConPrecioReal = [];
itemsCrudos.forEach(it => {
  const buscado = normalizarTexto(it.nombre);
  let match = menuItemsReal.find(m => normalizarTexto(m.nombre) === buscado);
  if (!match && buscado) {
    const parecidos = menuItemsReal.filter(m => {
      const n = normalizarTexto(m.nombre);
      return n.includes(buscado) || buscado.includes(n);
    });
    if (parecidos.length === 1) match = parecidos[0];
  }
  if (!match) { noEncontrados.push(it.nombre || '(sin nombre)'); return; }
  // Precio del menú activo cuando se añadió el plato (la carta ya viene con
  // los precios del menú). Un plato que ya estaba en el pedido conserva su
  // precio, así el resumen y el pedido final cuadran aunque entre medias
  // empiece otro menú (p. ej. a las 21:00).
  const previo = (pedidoActual.items || []).find(p => p.nombre === match.nombre);
  itemsConPrecioReal.push({
    ...it,
    nombre: match.nombre,
    emoji: match.emoji || it.emoji || null,
    notas: it.notas || null,
    precio: previo && previo.precio != null ? parseFloat(previo.precio) : parseFloat(match.precio),
    cantidad: Math.max(1, parseInt(it.cantidad) || 1)
  });
});

// Hora de recogida: se valida en cuanto el cliente la da, no al final.
// Antes el modelo contestaba "Perfecto, recogida a las 22:15" y el rechazo
// llegaba después de pedir nombre y teléfono.
// Si el modelo no devuelve la hora, se busca en el texto del cliente (solo
// formatos de hora claros, ver extraerHoraDelTexto), también en el primer
// mensaje: "quiero hacer un pedido para hoy a las 14hs".
const horaNueva = normalizarHora(parsed?.hora_recogida) || extraerHoraDelTexto(datos.mensajeTexto);
let horaRecogida = pedidoActual.hora_recogida || null;
let avisoHora = null;
// Solo pedidos para hoy: "para mañana a las 14" no puede guardarse como
// las 14:00 de hoy.
const textoNormalizado = normalizarTexto(datos.mensajeTexto);
const DIAS_SIN_TILDE = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const diaPedido = (textoNormalizado.match(/\bpara el (lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b/) || [])[1];
const paraOtroDia = /\b(para|hasta) (manana|pasado manana)\b|\bpasado manana\b/.test(textoNormalizado)
  || (diaPedido && DIAS_SIN_TILDE.indexOf(diaPedido) !== ahoraMadrid().dia);
if (paraOtroDia) {
  const tramosHoy = datos.horarioConfig
    ? tramosDisponibles(franjasVigentes(datos.horarioConfig, ahoraMadrid(), datos.takeawayMinutosAntesCierre || 0), ahoraMadrid().min)
    : null;
  avisoHora = 'De momento solo preparamos pedidos para recoger hoy, no para otro día.'
    + (tramosHoy === null ? ' ¿A qué hora de hoy te viene bien?'
      : tramosHoy.length ? ` Hoy puedes recogerlo ${textoTramos(tramosHoy)}. ¿Te viene bien alguna hora?`
      : ' Y por hoy ya no aceptamos más pedidos. ¡Te esperamos otro día!');
  horaRecogida = null;
} else if (horaNueva && horaNueva !== pedidoActual.hora_recogida) {
  const v = datos.horarioConfig
    ? validarHoraRecogida(horaNueva, franjasVigentes(datos.horarioConfig, ahoraMadrid(), datos.takeawayMinutosAntesCierre || 0), ahoraMadrid().min)
    : { ok: true, hora: horaNueva };
  if (v.ok) { horaRecogida = v.hora; } else { horaRecogida = null; avisoHora = v.mensaje; }
}

const datosMergeados = {
  items: itemsConPrecioReal,
  hora_recogida: horaRecogida,
  nombre_cliente: parsed?.nombre_cliente || pedidoActual.nombre_cliente || null,
  telefono_cliente: parsed?.telefono_cliente || pedidoActual.telefono_cliente || null
};

if (parsed && parsed.accion === 'cancelar') {
  return [{ json: {
    ...datos,
    intencion: 'general',
    accionPedido: 'cancelar',
    datosPedidoEnCurso: {},
    mensajeRespuesta: parsed.mensaje || 'De acuerdo, hemos cancelado el pedido. Hay algo mas en lo que pueda ayudarte?'
  }}];
}

// Pedido demasiado grande para WhatsApp (decisión 5): se avisa al momento,
// no se crea nada y queda un aviso pedido_demasiado_grande para el panel.
const unidadesPorPlato = {};
datosMergeados.items.forEach(it => {
  unidadesPorPlato[it.nombre] = (unidadesPorPlato[it.nombre] || 0) + (parseInt(it.cantidad) || 1);
});
const unidadesTotales = Object.values(unidadesPorPlato).reduce((a, b) => a + b, 0);
if (datosMergeados.items.length > MAX_LINEAS || unidadesTotales > MAX_UNIDADES
    || Object.values(unidadesPorPlato).some(n => n > MAX_POR_PLATO)) {
  await registrarFallo(this.helpers, datos, 'pedido_demasiado_grande', 'Procesar respuesta takeaway',
    'Pedido por encima del máximo de WhatsApp', { unidades: unidadesTotales, lineas: datosMergeados.items.length });
  return [{ json: {
    ...datos,
    intencion: 'general',
    accionPedido: 'cancelar',
    datosPedidoEnCurso: {},
    mensajeRespuesta: mensajePedidoGrande()
  }}];
}

// Mensaje de corrección propio cuando algo no cuadra: tiene prioridad
// sobre lo que haya escrito el modelo, y nunca se confirma el pedido.
let correccion = null;
if (noEncontrados.length > 0) {
  correccion = `Perdona, no encuentro ${noEncontrados.map(n => `"${n}"`).join(', ')} en nuestra carta. ¿Quieres pedir otra cosa en su lugar?`;
  if (avisoHora) correccion += `\n\n${avisoHora}`;
} else if (avisoHora) {
  correccion = datosMergeados.items.length === 0
    ? `${avisoHora} Si te va bien, dime qué te gustaría pedir y te muestro la carta.`
    : avisoHora;
} else if (parsed && parsed.accion === 'confirmar_pedido') {
  if (datosMergeados.items.length === 0) correccion = '¿Qué te gustaría pedir?';
  else if (!datosMergeados.hora_recogida) correccion = '¿A qué hora quieres pasar a recogerlo?';
  else if (!datosMergeados.nombre_cliente) correccion = '¿A nombre de quién dejo el pedido?';
}

// Confirmación en dos pasos, como en reservas: cuando el pedido está
// completo el sistema manda el resumen con el total (calculado aquí, nunca
// por el modelo) y espera un "sí". Solo entonces se crea el pedido. Antes
// se creaba en cuanto el modelo lo daba por completo, sin que el cliente
// viera el total.
const completo = datosMergeados.items.length > 0 && datosMergeados.hora_recogida && datosMergeados.nombre_cliente;
const esperandoConfirmacion = datos.estadoActual === 'pendiente_confirmacion_pedido';
// Clave del pedido (idempotencia en fn_pedido_whatsapp_crear): se crea al
// mandar un resumen nuevo y viaja en datosPedidoEnCurso hasta el "sí".
const nuevaClavePedido = () => 'wa-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
const firmaPedido = p => JSON.stringify({
  items: (p.items || []).map(it => [it.nombre, parseInt(it.cantidad) || 1, it.notas || null]),
  hora: p.hora_recogida || null,
  nombre: p.nombre_cliente || null
});
const sinCambios = firmaPedido(datosMergeados) === firmaPedido(pedidoActual);
const firmaItems = items => JSON.stringify((items || []).map(it => [it.nombre, parseInt(it.cantidad) || 1, it.notas || null]));
const itemsCambiaron = firmaItems(datosMergeados.items) !== firmaItems(pedidoActual.items);
const textoCliente = normalizarTexto(datos.mensajeTexto).replace(/[!.¡¿?,]/g, '').trim();
// "¿cuánto es?", "revisa la cuenta", "me parece que has sumado mal"...
const pideTotal = /\b(total|cuenta|suma|sumad[oa]s?|importe|cuanto (es|son|sale|seria|serian|te debo|le debo|cuesta todo|va todo|llevo|pago))\b/.test(textoCliente);
const negativo = /^no\b/.test(textoCliente);
const diceSi = /^(si|sip|vale|ok|okay|okey|dale|confirmo|confirmado|correcto|perfecto|adelante|de acuerdo|claro|eso es|asi es)( (si|vale|gracias|por favor|perfecto|confirmo|esta bien|todo bien|correcto))*$/.test(textoCliente);

if (!correccion && completo && esperandoConfirmacion && sinCambios
    && (diceSi || (parsed && parsed.accion === 'confirmar_pedido'))) {
  return [{ json: {
    ...datos,
    intencion: 'takeaway',
    accionPedido: 'confirmar',
    datosPedidoEnCurso: { ...datosMergeados, clave_pedido: pedidoActual.clave_pedido || null },
    mensajeRespuesta: null
  }}];
}

// Importes: SIEMPRE calculados aquí con los precios de la carta, nunca por
// el modelo (el 9 nov, tras cambiar una merluza por un secreto, el modelo
// dijo "el total sigue siendo 166,50€" y eran 167,00€).
const euros = n => formatMoney(n, monedaRestaurante());
const total = datosMergeados.items.reduce((s, it) => s + parseFloat(it.precio) * (parseInt(it.cantidad) || 1), 0);
const lineasPedido = datosMergeados.items.map(it =>
  `${it.emoji || '•'} ${it.nombre} x${parseInt(it.cantidad) || 1} — ${euros(parseFloat(it.precio) * (parseInt(it.cantidad) || 1))}${it.notas ? ' (' + it.notas + ')' : ''}`
).join('\n');

// Resumen final con el total para que el cliente confirme. Se manda cuando
// el pedido está completo y el modelo lo da por terminado, o cuando, con la
// confirmación pendiente, el cliente cambia algo o pregunta el total.
if (!correccion && completo && ((parsed && parsed.accion === 'confirmar_pedido')
    || (esperandoConfirmacion && (!sinCambios || pideTotal)))) {
  // Teléfono que se guardará: el que dio el cliente o el de WhatsApp, en el
  // mismo formato que fn_normalizar_telefono (españoles sin el 34).
  const telefonoResumen = (() => {
    const t = String(datosMergeados.telefono_cliente || datos.telefono || '').replace(/\D/g, '').replace(/^00/, '');
    return /^34[6789]\d{8}$/.test(t) ? t.slice(2) : t;
  })();
  const resumen = `Te resumo tu pedido:\n\n${lineasPedido}\n\n💰 *Total: ${euros(total)}*\n🕐 *Recogida:* ${datosMergeados.hora_recogida}\n👤 *Nombre:* ${datosMergeados.nombre_cliente}\n📞 *Teléfono:* ${telefonoResumen}\n\n¿Confirmo el pedido? (responde *sí* o dime qué quieres cambiar)`;
  return [{ json: {
    ...datos,
    intencion: 'takeaway',
    accionPedido: 'pedir_confirmacion',
    // Mismo resumen (p. ej. "¿cuánto es?") → misma clave; resumen cambiado → nueva.
    datosPedidoEnCurso: { ...datosMergeados, clave_pedido: (sinCambios && pedidoActual.clave_pedido) || nuevaClavePedido() },
    mensajeRespuesta: resumen
  }}];
}

function siguientePregunta() {
  if (datosMergeados.items.length === 0) return '¿Qué te gustaría pedir?';
  if (!datosMergeados.hora_recogida) return '¿A qué hora quieres pasar a recogerlo?';
  if (!datosMergeados.nombre_cliente) return '¿A nombre de quién dejo el pedido?';
  return '¿Quieres algo más o te paso el resumen para confirmar?';
}

// Quita del texto del modelo las frases con importes ("El total sigue
// siendo 166,50€"): los pone el sistema en el bloque del pedido. Se quitan
// frases, no líneas, para no perder la pregunta que va en la misma línea.
function sinImportes(texto) {
  const conImporte = s => /[\u20AC$]|\beur(os)?\b|\btotal\b|\bsubtotal\b/i.test(s);
  return String(texto || '').split('\n')
    .map(l => conImporte(l) ? (l.match(/[^.!?]+[.!?]*\s*/g) || []).filter(s => !conImporte(s)).join('').trim() : l)
    .join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

// Bloque con el pedido y el total cuando cambian los platos o el cliente
// pregunta la cuenta.
const bloquePedido = (itemsCambiaron || pideTotal) && datosMergeados.items.length > 0
  ? `🧾 *Tu pedido:*\n${lineasPedido}\n\n💰 *Total: ${euros(total)}*`
  : null;

let texto;
if (correccion) texto = correccion;
else if (!parsed) texto = datosMergeados.items.length ? siguientePregunta() : 'Perdona, no te he entendido bien. ¿Me lo repites?';
else texto = bloquePedido ? sinImportes(parsed.mensaje) : String(parsed.mensaje || '').trim();
if (!texto) texto = siguientePregunta();
let mensaje = bloquePedido ? `${bloquePedido}\n\n${texto}` : texto;

// Con el resumen ya enviado y sin cambios (p. ej. una pregunta suelta), se
// responde y se sigue esperando la confirmación, sin volver a empezar.
if (!correccion && parsed && completo && esperandoConfirmacion && sinCambios && !negativo) {
  return [{ json: {
    ...datos,
    intencion: 'takeaway',
    accionPedido: 'pedir_confirmacion',
    datosPedidoEnCurso: { ...datosMergeados, clave_pedido: pedidoActual.clave_pedido || nuevaClavePedido() },
    mensajeRespuesta: `${mensaje}\n\n¿Confirmo el pedido? (responde *sí* o dime qué quieres cambiar)`
  }}];
}

return [{ json: {
  ...datos,
  intencion: 'takeaway',
  accionPedido: 'continuar',
  datosPedidoEnCurso: datosMergeados,
  mensajeRespuesta: mensaje
}}];

// Crea el pedido con fn_pedido_whatsapp_crear: orders + order_items en una
// sola transacción, con el precio de la carta (la BD ignora el que mandemos)
// y sin duplicados (E1, E2, S3). "✅ Pedido confirmado" solo sale con un id
// devuelto por la BD.
// --- Comunes del agente (revisión 1a, docs/specs/2026-11-13-agente-whatsapp-revision.md)
// Supabase con reintentos. Devuelve { ok, status, body }: reintenta los
// fallos de red y los 5xx; un 4xx (datos no válidos, validación de la BD) se
// devuelve sin reintentar. Si sigue fallando, lanza el último error.
async function llamarSupabase(helpers, metodo, ruta, cuerpo, intentos = 3) {
  let ultimoError = null;
  for (let i = 0; i < intentos; i++) {
    try {
      const r = await helpers.httpRequest({
        method: metodo,
        url: `${$env.SUPABASE_URL}${ruta}`,
        headers: {
          'apikey': $env.SUPABASE_SERVICE_ROLE_KEY,
          'Authorization': 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY,
          'Content-Type': 'application/json'
        },
        body: cuerpo,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
      });
      const status = Number(r?.statusCode || 0);
      if (status >= 200 && status < 300) return { ok: true, status, body: r.body };
      if (status >= 400 && status < 500) return { ok: false, status, body: r.body };
      ultimoError = new Error(`Supabase respondió ${status}`);
    } catch (e) {
      ultimoError = e;
    }
    if (i < intentos - 1) {
      try { await new Promise(res => setTimeout(res, 700 * (i + 1))); } catch (e) { /* sin espera */ }
    }
  }
  throw ultimoError || new Error('Supabase no responde');
}

// Registra un aviso en agente_errores (fn_agente_registrar_error). Nunca
// lanza: si no se puede registrar, el flujo sigue y el cliente recibe su
// respuesta. Si falla el registro con detalle, se intenta una sola vez el
// aviso mínimo 'registro_fallido' (sin reintentos en cadena). En el detalle
// nunca van claves ni la conversación.
async function registrarFallo(helpers, base, tipo, paso, error, extra = {}) {
  const texto = String((error && (error.message || error.description)) || error || '').slice(0, 500);
  let ejecucion = null;
  try { ejecucion = $execution.id; } catch (e) { /* sin id */ }
  try {
    const r = await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: (base && base.restaurant_id) || null,
      p_telefono: (base && base.telefono) || null,
      p_tipo: tipo,
      p_paso: paso,
      p_detalle: { error: texto, ejecucion, ...extra }
    }, 2);
    if (r.ok) return true;
  } catch (e) { /* sigue */ }
  try {
    await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: null, p_telefono: null, p_tipo: 'registro_fallido', p_paso: paso,
      p_detalle: { tipo_original: tipo, ejecucion }
    }, 1);
  } catch (e) { /* sin registro */ }
  return false;
}

const MENSAJE_PROBLEMA_TECNICO = 'Perdona, ahora mismo tengo un problema técnico. ¿Me lo repites en un momento?';
// --- Fin de comunes ----------------------------------------------------------
// --- Dinero: mismo resultado que formatMoney() de src/lib/money.js ----------
// (misma tabla moneda → idioma; nunca un símbolo de moneda escrito a mano).
const LOCALE_POR_MONEDA = { EUR: 'es-ES', USD: 'en-US', MXN: 'es-MX', ARS: 'es-AR', COP: 'es-CO', CLP: 'es-CL', PEN: 'es-PE' };
function formatMoney(amount, currencyCode = 'EUR') {
  const monto = typeof amount === 'string' ? parseFloat(amount) : amount;
  const valor = Number.isFinite(monto) ? monto : 0;
  const locale = LOCALE_POR_MONEDA[currencyCode] || 'es-ES';
  try {
    return new Intl.NumberFormat(locale, { style: 'currency', currency: currencyCode }).format(valor);
  } catch (e) {
    return `${valor.toFixed(2)} ${currencyCode}`;
  }
}
function monedaRestaurante() {
  try { return $('Verificar restaurante y módulo whatsapp').first().json.moneda || 'EUR'; } catch (e) { return 'EUR'; }
}
// --- Fin de dinero -------------------------------------------------------------
// Tope por pedido de WhatsApp (decisión 5): igual que fn_pedido_whatsapp_crear.
const MAX_POR_PLATO = 20;
const MAX_UNIDADES = 60;
const MAX_LINEAS = 30;
function mensajePedidoGrande() {
  let tel = null;
  try { tel = $('Verificar restaurante y módulo whatsapp').first().json.telefono_restaurante || null; } catch (e) { /* sin teléfono */ }
  return `Por WhatsApp podemos preparar como máximo ${MAX_POR_PLATO} unidades de cada plato y ${MAX_UNIDADES} en total. `
    + (tel ? `Para pedidos tan grandes, llámanos al ${tel} y lo preparamos contigo.`
           : 'Para pedidos tan grandes, contacta directamente con el restaurante y lo preparamos contigo.');
}
function normalizarTexto(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
}
// Hash corto y estable (FNV-1a) para la clave del pedido.
function hashCorto(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(36);
}

const d = $json;
const p = d.datosPedidoEnCurso || {};
const moneda = monedaRestaurante();
const sesion = $('Combinar con sesión').first().json;
let menuItems = [];
try { menuItems = $('Preparar takeaway').first().json.menuItems || []; } catch (e) { /* sin carta */ }
const buscar = nombre => menuItems.find(m => normalizarTexto(m.nombre) === normalizarTexto(nombre));
const items = p.items || [];
const salida = extra => [{ json: {
  telefono: d.telefono,
  restaurant_id: d.restaurant_id,
  restaurant_nombre: d.restaurant_nombre,
  contexto: d.contexto,
  intencion: 'takeaway',
  ...extra
} }];
const unidades = it => parseInt(it.cantidad) || 1;
const lineaResumen = it => `${it.emoji || '•'} ${it.nombre} x${unidades(it)} — ${formatMoney(parseFloat(it.precio) * unidades(it), moneda)}${it.notas ? ' (' + it.notas + ')' : ''}`;

// 1) ¿Ha cambiado la carta desde el resumen? Platos que ya no están, o con
//    otro precio: no se crea nada y se manda un resumen nuevo.
const faltan = items.filter(it => !buscar(it.nombre)).map(it => it.nombre);
if (faltan.length) {
  return salida({
    accionPedido: 'continuar',
    datosPedidoEnCurso: { ...p, items: items.filter(it => buscar(it.nombre)) },
    mensajeRespuesta: `Perdona, ${faltan.map(n => `"${n}"`).join(', ')} ya no está disponible ahora mismo. ¿Quieres pedir otra cosa en su lugar?`
  });
}
const cambiados = items.filter(it => Math.abs(parseFloat(buscar(it.nombre).precio) - parseFloat(it.precio)) > 0.001);
if (cambiados.length) {
  const nuevos = items.map(it => ({ ...it, precio: parseFloat(buscar(it.nombre).precio) }));
  const total = nuevos.reduce((s, it) => s + parseFloat(it.precio) * unidades(it), 0);
  return salida({
    accionPedido: 'pedir_confirmacion',
    // Resumen nuevo → clave nueva.
    datosPedidoEnCurso: { ...p, items: nuevos, clave_pedido: 'wa-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10) },
    mensajeRespuesta: `Perdona, el precio de ${cambiados.map(it => it.nombre).join(', ')} ha cambiado desde el resumen. Te lo paso actualizado:\n\n${nuevos.map(lineaResumen).join('\n')}\n\n💰 *Total: ${formatMoney(total, moneda)}*\n🕐 *Recogida:* ${p.hora_recogida}\n👤 *Nombre:* ${p.nombre_cliente}\n\n¿Confirmo el pedido? (responde *sí* o dime qué quieres cambiar)`
  });
}

// 2) Clave del pedido: la crea "Procesar respuesta takeaway" al mandar el
//    resumen y viaja en el pedido en curso, así dos "sí" seguidos, o un "sí"
//    repetido tras un problema técnico, dan la misma clave → un solo pedido.
//    Se le añade el hash del pedido: si algo cambiara sin resumen nuevo, la
//    clave también cambia. Las sesiones de antes del despliegue (sin clave)
//    usan la versión de la sesión.
const firma = JSON.stringify({
  items: items.map(it => [it.nombre, unidades(it), it.notas || null]),
  hora: p.hora_recogida || null,
  nombre: p.nombre_cliente || null
});
const clave = `${p.clave_pedido || `wa-${sesion.sesion_id || d.telefono}-${sesion.sesion_updated_at ? Date.parse(sesion.sesion_updated_at) : 0}`}-${hashCorto(firma)}`;

const tecnico = () => salida({
  // Se conserva el pedido con su clave_pedido: si el cliente vuelve a decir
  // "sí" y el primer intento sí llegó a crearse en la BD, la misma clave
  // devuelve ese pedido (ya_existia) en vez de crear otro.
  accionPedido: 'pedir_confirmacion',
  datosPedidoEnCurso: p,
  mensajeRespuesta: MENSAJE_PROBLEMA_TECNICO
});

let r;
try {
  r = await llamarSupabase(this.helpers, 'POST', '/rest/v1/rpc/fn_pedido_whatsapp_crear', {
    p_restaurant_id: d.restaurant_id,
    p_clave: clave,
    // Si el cliente no dio otro teléfono, el de WhatsApp.
    p_telefono: p.telefono_cliente || d.telefono,
    p_nombre: p.nombre_cliente || null,
    // timestamptz: "2026-11-07 21:30 Europe/Madrid"; Postgres aplica el
    // desfase de verano/invierno.
    p_hora_recogida: (p.fecha_recogida && p.hora_recogida) ? `${p.fecha_recogida} ${p.hora_recogida} Europe/Madrid` : null,
    p_notas: null,
    p_items: items.map(it => ({ menu_item_id: buscar(it.nombre).id, cantidad: unidades(it), notas: it.notas || null }))
  });
} catch (e) {
  await registrarFallo(this.helpers, d, 'pedido_no_creado', 'Preparar pedido datos', e);
  return tecnico();
}

if (!r.ok) {
  const code = r.body?.code || null;
  if (code === 'RMP01') {
    await registrarFallo(this.helpers, d, 'pedido_demasiado_grande', 'Preparar pedido datos', r.body?.message || 'RMP01');
    return salida({ intencion: 'general', accionPedido: 'cancelar', datosPedidoEnCurso: {}, mensajeRespuesta: mensajePedidoGrande() });
  }
  if (code === 'RMP02') {
    return salida({
      accionPedido: 'continuar',
      datosPedidoEnCurso: { ...p, items: [] },
      mensajeRespuesta: 'Perdona, algún plato de tu pedido ya no está disponible ahora mismo. ¿Me dices otra vez qué quieres pedir?'
    });
  }
  if (code === 'RMP04') {
    return salida({ intencion: 'general', accionPedido: 'cancelar', datosPedidoEnCurso: {},
      mensajeRespuesta: 'Lo siento, ahora mismo no podemos aceptar pedidos para recoger.' });
  }
  await registrarFallo(this.helpers, d, 'pedido_no_creado', 'Preparar pedido datos',
    `HTTP ${r.status} ${code || ''}: ${String(r.body?.message || '').slice(0, 300)}`);
  return tecnico();
}

const res = r.body || {};
if (!res.id) {
  await registrarFallo(this.helpers, d, 'pedido_no_creado', 'Preparar pedido datos', 'La BD no devolvió el id del pedido');
  return tecnico();
}

if (res.ya_existia) {
  // Segundo "sí" del mismo pedido: no se duplica ni se vuelve a mandar el ✅.
  return salida({ intencion: 'general', accionPedido: null, datosPedidoEnCurso: {},
    mensajeRespuesta: `Tu pedido ya está registrado, no lo he duplicado. Te esperamos a las ${p.hora_recogida}. 🍽` });
}

// Importes de la BD (los que se cobran), no los del resumen.
const emojiDe = nombre => (buscar(nombre) || {}).emoji || '•';
const lineas = (res.lineas || []).map(l =>
  `${emojiDe(l.nombre)} ${l.nombre} x${l.cantidad} — ${formatMoney(Number(l.precio) * Number(l.cantidad), moneda)}${l.notas ? ' (' + l.notas + ')' : ''}`
).join('\n');
const mensajeConfirmacion = `✅ *Pedido confirmado para recoger en ${d.restaurant_nombre}!*\n\n${lineas}\n\n💰 *Total: ${formatMoney(Number(res.total), moneda)}*\n🕐 *Hora de recogida: ${p.hora_recogida || 'a confirmar'}*\n👤 *Nombre: ${p.nombre_cliente || ''}*\n\nTe esperamos! 🍽`;

return salida({
  // 'general', no 'takeaway': el pedido ya quedó confirmado (así el atajo
  // del clasificador no fuerza el siguiente mensaje a takeaway).
  intencion: 'general',
  accionPedido: null,
  datosPedidoEnCurso: {},
  mensajeRespuesta: mensajeConfirmacion,
  order_id: res.id
});

