// Meta firma los bytes exactos del cuerpo (X-Hub-Signature-256). El webhook
// lo recibe en bruto (opción Raw Body, binario "data") y aquí se pasa a texto
// UTF-8 SIN tocarlo: nada de JSON.parse/stringify antes de comprobar la firma.
const item = $input.first();
let cuerpoBruto = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  cuerpoBruto = buf.toString('utf8');
} catch (e) {
  const b64 = item.binary?.data?.data;
  cuerpoBruto = b64 ? Buffer.from(b64, 'base64').toString('utf8') : '';
}
const cabeceras = item.json.headers || {};
return [{ json: { cuerpoBruto, firmaRecibida: String(cabeceras['x-hub-signature-256'] || '') } }];

// Compara la firma de Meta ("sha256=<hex>") con el HMAC-SHA256 del cuerpo en
// bruto calculado en "Calcular firma" con el app secret de RestomindWapp
// ($env.META_APP_SECRET_RESTOMIND, nunca en el JSON). La comparación recorre
// siempre toda la longitud (no sale al primer carácter distinto). El cuerpo
// se convierte a JSON solo si la firma es válida. La firma recibida no se
// guarda en ningún sitio.
const leido = $('Leer cuerpo en bruto').first().json;
const calculada = String($input.first().json.firmaCalculada || '');
const secretoConfigurado = String($env.META_APP_SECRET_RESTOMIND || '') !== '';
const esperada = 'sha256=' + calculada;
const recibida = String(leido.firmaRecibida || '');

let diferencia = (esperada.length ^ recibida.length) | (calculada.length === 64 ? 0 : 1) | (secretoConfigurado ? 0 : 1);
const largo = Math.max(esperada.length, recibida.length);
for (let i = 0; i < largo; i++) {
  diferencia |= (esperada.charCodeAt(i) || 0) ^ (recibida.charCodeAt(i) || 0);
}

if (diferencia !== 0) {
  return [{ json: {
    firmaValida: false,
    motivo: !secretoConfigurado ? 'falta META_APP_SECRET_RESTOMIND en n8n'
      : recibida ? 'firma distinta' : 'sin cabecera X-Hub-Signature-256'
  } }];
}

let aviso = null;
try { aviso = JSON.parse(leido.cuerpoBruto); } catch (e) { aviso = null; }
return [{ json: { firmaValida: true, aviso } }];

// POST sin firma válida de Meta: ya se respondió 403. Se registra
// firma_invalida (sin restaurante ni teléfono: no son fiables; la BD agrupa
// todas en una fila por media hora) y termina: no se busca restaurante, ni se
// llama a la IA, ni se escribe nada más.
// --- Comunes del agente (revisión 1a, docs/specs/2026-11-13-agente-whatsapp-revision.md)
// Supabase con reintentos. Devuelve { ok, status, body }: reintenta los
// fallos de red y los 5xx; un 4xx (datos no válidos, validación de la BD) se
// devuelve sin reintentar. Si sigue fallando, lanza el último error.
async function llamarSupabase(helpers, metodo, ruta, cuerpo, intentos = 3) {
  let ultimoError = null;
  for (let i = 0; i < intentos; i++) {
    try {
      const r = await helpers.httpRequest({
        method: metodo,
        url: `${$env.SUPABASE_URL}${ruta}`,
        headers: {
          'apikey': $env.SUPABASE_SERVICE_ROLE_KEY,
          'Authorization': 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY,
          'Content-Type': 'application/json'
        },
        body: cuerpo,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
      });
      const status = Number(r?.statusCode || 0);
      if (status >= 200 && status < 300) return { ok: true, status, body: r.body };
      if (status >= 400 && status < 500) return { ok: false, status, body: r.body };
      ultimoError = new Error(`Supabase respondió ${status}`);
    } catch (e) {
      ultimoError = e;
    }
    if (i < intentos - 1) {
      try { await new Promise(res => setTimeout(res, 700 * (i + 1))); } catch (e) { /* sin espera */ }
    }
  }
  throw ultimoError || new Error('Supabase no responde');
}

// Registra un aviso en agente_errores (fn_agente_registrar_error). Nunca
// lanza: si no se puede registrar, el flujo sigue y el cliente recibe su
// respuesta. Si falla el registro con detalle, se intenta una sola vez el
// aviso mínimo 'registro_fallido' (sin reintentos en cadena). En el detalle
// nunca van claves ni la conversación.
async function registrarFallo(helpers, base, tipo, paso, error, extra = {}) {
  const texto = String((error && (error.message || error.description)) || error || '').slice(0, 500);
  let ejecucion = null;
  try { ejecucion = $execution.id; } catch (e) { /* sin id */ }
  try {
    const r = await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: (base && base.restaurant_id) || null,
      p_telefono: (base && base.telefono) || null,
      p_tipo: tipo,
      p_paso: paso,
      p_detalle: { error: texto, ejecucion, ...extra }
    }, 2);
    if (r.ok) return true;
  } catch (e) { /* sigue */ }
  try {
    await llamarSupabase(helpers, 'POST', '/rest/v1/rpc/fn_agente_registrar_error', {
      p_restaurant_id: null, p_telefono: null, p_tipo: 'registro_fallido', p_paso: paso,
      p_detalle: { tipo_original: tipo, ejecucion }
    }, 1);
  } catch (e) { /* sin registro */ }
  return false;
}

