// E4: WhatsApp no admite textos de más de 4.096 caracteres (la carta entera
// los supera). Se envía en varios mensajes, en orden, cortados por final de
// línea. Un item por mensaje: "Enviar respuesta WhatsApp" los manda de uno en uno.
// Parte un texto en mensajes de 4.096 caracteres como máximo (límite de
// WhatsApp), cortando por final de línea. Una línea sola más larga se corta
// por el último espacio.
const MAX_WHATSAPP = 4096;
function partirMensaje(texto, max = MAX_WHATSAPP) {
  const t = String(texto || '');
  if (t.length <= max) return [t];
  const partes = [];
  let actual = '';
  for (const linea of t.split('\n')) {
    let resto = linea;
    while (resto.length > max) {
      if (actual) { partes.push(actual); actual = ''; }
      let corte = resto.lastIndexOf(' ', max);
      if (corte <= 0) corte = max;
      partes.push(resto.slice(0, corte));
      resto = resto.slice(corte).replace(/^ /, '');
    }
    const candidato = actual ? actual + '\n' + resto : resto;
    if (candidato.length > max) { partes.push(actual); actual = resto; }
    else actual = candidato;
  }
  if (actual) partes.push(actual);
  return partes.filter(p => p.trim() !== '');
}
const d = $input.first().json;
const partes = partirMensaje(d.mensajeRespuesta || '¡Hola! ¿En qué puedo ayudarte?');
return partes.map((texto, i) => ({ json: {
  telefono: d.telefono,
  restaurant_id: d.restaurant_id,
  texto,
  parte: i + 1,
  partes: partes.length
} }));

